constexpr const std::pair<std::uint16_t, std::uint8_t> *Dictionary[3] = {
	&Dictionary0[0], &Dictionary1[0], &Dictionary2[0]};
/**
 * Tests if the matrix is invertible by checking the rows are linearly
 * independent in GF(2).
 * @param {number[]} rows
 * @returns {boolean}
 */
__attribute__((noinline)) 
std::pair<bool, std::size_t> isInvertible(const std::vector<std::uint16_t> &matrix) {
	// We want this test to be as fast as possible, since we spend the vast majority of our time testing if matrices are invertible.
	std::uint16_t basis[16]{};
	auto curr = matrix.cbegin();
	do {
		std::uint16_t v = *curr;
		do {
			std::uint16_t b = 15 - __builtin_clzs(v);
			if (!basis[b]) {
				basis[b] = v;
				break;
			}
			v ^= basis[b];
			if (!v)
				return { false, curr - matrix.cbegin() };
		} while (true);
	} while (++curr < matrix.cend());
	return { true, 0 };
}

__attribute__((noinline)) bool
invertMatrix(const std::vector<std::uint16_t> &matrix,
			 std::vector<std::uint32_t> &scratch,
			 std::vector<std::uint16_t> &output) {
	for (std::size_t i = 0; i < matrix.size(); i++) {
		scratch[i] = matrix[i] | (1 << (16 + i));
	}
	std::uint32_t mask = 1;
	for (auto currI = scratch.begin(); currI < scratch.end(); currI++) {
		for (auto currJ = currI; currJ < scratch.end(); currJ++) {
			if ((*currJ) & mask) {
				std::swap(*currI, *currJ);
				break;
			}
		}
		for (auto currJ = currI + 1; currJ < scratch.end(); currJ++) {
			if ((*currJ) & mask) {
				*currJ ^= *currI;
			}
		}
		mask <<= 1;
	}
	auto currI = scratch.end();
	while (currI-- != scratch.begin()) {
		mask >>= 1;
		auto currJ = currI;
		while (currJ-- != scratch.begin()) {
			if ((*currJ) & mask) {
				*currJ ^= *currI;
			}
		}
	}
	for (std::size_t i = 0; i < scratch.size(); i++) {
		output[i] = scratch[i] >> 16;
	}
	return true;
}

std::vector<std::uint16_t> transition(const std::vector<std::uint16_t> &rows, const std::vector<std::uint16_t> &terms) {
	std::vector<std::uint16_t> new_terms(terms.size());
	for (std::size_t i = 0; i < terms.size(); i++) {
		std::uint16_t bitmask = 1;
		for (std::size_t j = 0; j < terms.size(); j++) {
			if (rows[i] & bitmask) {
				new_terms[i] ^= terms[j];
			}
			bitmask <<= 1;
		}
	}
	return new_terms;
}

std::vector<std::uint16_t> transpose(const std::vector<std::uint16_t> &matrix) {
	std::vector<std::uint16_t> result(matrix.size());
	for (std::size_t i = 0; i < matrix.size(); i++) {
		std::uint16_t beginning = (matrix[0] >> i) & 1;
		for (std::size_t j = 1; j < matrix.size(); j++) {
			beginning |= ((matrix[j] >> i) & 1) << j;
		}
		result[i] = beginning;
	}
	return result;
}

struct Precursor {
	std::uint8_t lampCount;
	std::uint16_t precursor;
	std::uint16_t combination;
	Precursor(std::uint8_t lc, std::uint16_t p, std::uint16_t c)
		: lampCount(lc), precursor(p), combination(c) {}
};

std::size_t sizes[] = {16, 256, 12960};

std::size_t full_sizes[] = {16, 256, 65536};

__attribute__((noinline))
std::pair<std::vector<std::uint16_t>,
		  std::vector<std::uint8_t>>
getGoodTerms(std::size_t varCount, const std::vector<std::uint16_t> &terms,
			 std::uint16_t mask) {
	
	const auto &dictionary = Dictionary[varCount - 2];
	
	std::size_t size = sizes[varCount - 2];
	
	std::vector<std::uint8_t> maskedDictionary(full_sizes[varCount - 2], 255);
	
	for (std::size_t i = 0; i < size; i++) {
		const auto& [term, complexity] = dictionary[i];
		auto& oldComplexity = maskedDictionary[term | mask];
		if (complexity < oldComplexity) { // replacing this with std::min does cursed things
			oldComplexity = complexity;
		}
	}

	std::vector<Precursor> precursorTerms;
	precursorTerms.reserve(1 << terms.size());
	for (std::uint16_t combination = 1; combination < 1 << terms.size(); combination++) {
		std::uint16_t bitmask = 0b1;
		std::uint16_t precursor = 0b0;
		for (std::size_t i = 0; i < terms.size(); i++) {
			if ((combination & bitmask)) {
				precursor ^= terms[i];
			}
			bitmask <<= 1;
		}

		auto minComplexity = maskedDictionary.at(precursor | mask);
		if (minComplexity != 255) {
			precursorTerms.emplace_back(minComplexity, precursor, combination);
		}
	}

	std::stable_sort(precursorTerms.begin(), precursorTerms.end(),
					 [](const Precursor &a, const Precursor &b) -> bool {
						 return a.lampCount < b.lampCount;
					 });

	std::vector<std::uint16_t> rpt;
	rpt.reserve(precursorTerms.size());
	
	for (std::size_t i = 0; i < precursorTerms.size(); i++) {
		const auto &term = precursorTerms[i];
		rpt.emplace_back(term.combination);
	}
	return std::make_pair(std::move(rpt), std::move(maskedDictionary));
}

struct Result {
	std::vector<std::uint16_t> rows;
	std::vector<std::uint16_t> transitioned;
	std::uint16_t mask;
	std::uint8_t complexity;
};

typedef std::vector<std::uint16_t>::const_iterator cit_u16_t;

__attribute__((noinline)) bool nextCombination(std::vector<cit_u16_t> &arr,
											   std::vector<std::uint16_t> &view,
											   cit_u16_t n, std::size_t m) {
	for (std::size_t i = m; i-- > 0;) {
		if (arr[i] < n - (m - i)) {
			auto last = ++arr[i];
			view[i] = *last;
			for (std::size_t j = i + 1; j < m; j++) {
				arr[j] = ++last;
				view[j] = *last;
			}
			return true;
		}
	}
	return false;
}

__attribute__((noinline)) bool nextCombinationWithProblematicIndex(std::vector<cit_u16_t> &arr,
											   std::vector<std::uint16_t> &view,
											   cit_u16_t n, std::size_t m, std::size_t problematicIndex) {
	for (std::size_t i = problematicIndex + 1; i-- > 0;) {
		if (arr[i] < n - (m - i)) {
			auto last = ++arr[i];
			view[i] = *last;
			for (std::size_t j = i + 1; j < m; j++) {
				arr[j] = ++last;
				view[j] = *last;
			}
			return true;
		}
	}
	return false;
}

std::vector<Result> combinations(std::size_t varCount,
								 std::vector<std::uint16_t> terms,
								 std::uint16_t mask = 0,
								 std::size_t hardLimit = 20) {
	const std::size_t terms_size = terms.size();

	const auto [linCombs, goodTermsMap] = getGoodTerms(varCount, terms, mask);

	std::vector<cit_u16_t> combination(terms_size);

	std::vector<std::uint16_t> lin_combination(terms_size, linCombs[0]);

	std::vector<Result> BigRes;
	std::vector<std::uint32_t> invert_scratch(terms_size);
	std::vector<std::uint16_t> invert_output(terms_size);

	for (std::size_t i = 0; i < terms_size; i++) {
		combination[i] = linCombs.cbegin() + i;
		lin_combination[i] = *combination[i];
	}
	do {
		// We want just... linearly independent matrixes.
		const auto [hasInverse, failingIndex] = isInvertible(lin_combination);
		if (hasInverse) {
			invertMatrix(lin_combination, invert_scratch, invert_output);
			const auto transitioned = transition(lin_combination, terms);
			const auto &inverse = invert_output;
			const auto rows = transpose(inverse);
			std::vector<std::uint16_t> new_transitioned;
			std::unordered_map<std::uint16_t, std::uint16_t> transitionedMap;

			for (std::size_t i = 0; i < transitioned.size(); i++) {
				std::uint16_t itransition = transitioned[i];
				if(itransition != 0) {
					auto itranIt = transitionedMap.find(itransition);
					if (itranIt != transitionedMap.end()) {
						itranIt->second ^= rows[i];
					} else {
						transitionedMap.emplace(itransition, rows[i]);
						new_transitioned.emplace_back(itransition);
					}
				}
			}

			std::vector<std::uint16_t> new_rows;
			new_rows.reserve(new_transitioned.size());

			std::uint8_t complexity_sum = 0;

			for (std::size_t i = 0; i < new_transitioned.size(); i++) {
				complexity_sum += goodTermsMap.at(new_transitioned[i] | mask);
				new_rows.emplace_back(transitionedMap.at(new_transitioned[i]));
			}

			BigRes.emplace_back(std::move(new_rows),
								std::move(new_transitioned), mask,
								complexity_sum);
		}
		if (BigRes.size() >= hardLimit) {
			break;
		}
		if(failingIndex) {
			if(!nextCombinationWithProblematicIndex(combination, lin_combination, linCombs.cend(), terms_size, failingIndex)) {
				break;
			}
		} else {
			if(!nextCombination(combination, lin_combination, linCombs.cend(), terms_size)) {
				break;
			}
		}
	} while (true);
	std::stable_sort(BigRes.begin(), BigRes.end(),
					 [](const auto &a, const auto &b) -> bool {
						 return a.complexity < b.complexity;
					 });
	return BigRes;
}

EMSCRIPTEN_BINDINGS(my_module) {
	emscripten::function("combinations", &combinations);
	emscripten::value_object<Result>("_")
		.field("complexity", &Result::complexity)
		.field("rows", &Result::rows)
		.field("transitioned", &Result::transitioned)
		.field("mask", &Result::mask);
}

namespace emscripten {
namespace internal {

template <typename T, typename Allocator>
struct BindingType<std::vector<T, Allocator>> {
	using ValBinding = BindingType<val>;
	using WireType = ValBinding::WireType;

	static WireType toWireType(const std::vector<T, Allocator> &vec,
							   rvp::default_tag) {
		return ValBinding::toWireType(val::array(vec), rvp::default_tag{});
	}

	static std::vector<T, Allocator> fromWireType(WireType value) {
		return vecFromJSArray<T>(ValBinding::fromWireType(value));
	}
};

template <typename T>
struct TypeID<
	T,
	typename std::enable_if_t<std::is_same<
		typename Canonicalized<T>::type,
		std::vector<typename Canonicalized<T>::type::value_type,
					typename Canonicalized<T>::type::allocator_type>>::value>> {
	static constexpr TYPEID get() { return TypeID<val>::get(); }
};

} // namespace internal
} // namespace emscripten